package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;

/** Changes the person's name and records the form's grade from its from-date (blank: the sheet's
 *  today), keeping the grades already recorded — except that a save leaving the grade as the row
 *  showed it (the one in force on the sheet's today), with the from-date blank, records none.
 *  The person's own terms, contact and tags become the form's (blank: none; tags not given: kept). */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, People people, Sheets sheets)
            throws InvalidSheetRequestException, PersonConflictException {
        if (request.version() != null && request.version() != person.getVersion()) {
            throw new PersonConflictException(PersonResponse.from(person));
        }
        check(request, person, people);
        applied(request, person, sheets);
    }

    /** Refused when the edit's name, an alias of the person, or the edit's contact is taken. */
    static void check(PersonRequest request, Person person, People people) throws InvalidSheetRequestException {
        if (people.nameUsedInTree(person.getSheetId(), request.name(), person.getId())) {
            throw new InvalidSheetRequestException("The name is already in use on this sheet or its tree");
        }
        // A person whose alias clashes with its tree cannot be edited until no alias clashes.
        Person renamed = new Person(person.getId(), person.getSheetId(), request.name(), person.getGrade());
        renamed.setAliases(person.getAliases());
        if (people.clashing(renamed)) {
            throw new InvalidSheetRequestException("An alias of this person is in use on another sheet of its tree");
        }
        if (request.contactKey() != null
                && people.contactTaken(person.getSheetId(), request.contactKey(), person.getId())) {
            throw new InvalidSheetRequestException("The contact is already in use on this sheet");
        }
    }

    /** Makes the checked edit to the person, ready to be saved. */
    static void applied(PersonRequest request, Person person, Sheets sheets) {
        person.setName(request.name());
        person.changeContact(request.contactKey());
        if (request.tags() != null) person.setTags(request.tagsKey());
        person.changeTerms(request.termsDays());
        LocalDate from = request.gradeFromDate();
        LocalDate today = sheets.today(person.getSheetId());
        person.setToday(today);
        if (from == null && request.grade().equals(person.getGrade())) return;
        person.recordGrade(request.grade(), from != null ? from : today);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import net.officefloor.hq.app.claim.ClaimRequest;
import net.officefloor.hq.app.sheet.InvalidSheetRequestException;

/** Body of a person add or edit: the name, the grade (A, B or C), who makes the change and, for an
 *  edit, the version of the person the editor loaded (null: no check), and the date the grade is
 *  in force from (yyyy-mm-dd; blank or null for the sheet's today), and the person's own terms in days
 *  (blank or null for none), and the person's contact (blank or null for none), and their tags, comma
 *  separated (blank for none; null keeps the tags they have). */
public record PersonRequest(String name, String grade, String user, Integer version, String gradeFrom, String terms,
        String contact, String tags) {

    public PersonRequest(String name, String grade, String user, Integer version, String gradeFrom, String terms,
            String contact) {
        this(name, grade, user, version, gradeFrom, terms, contact, null);
    }

    public PersonRequest(String name, String grade, String user, Integer version) {
        this(name, grade, user, version, null, null, null, null);
    }

    /** The contact given, without the spaces around it and lower-cased, or null when it was left blank. */
    public String contactKey() {
        return contact == null || contact.isBlank() ? null : contact.trim().toLowerCase(java.util.Locale.ROOT);
    }

    /** The tags given as stored (see {@link ClaimRequest#tags}), or null when none were given. */
    public String tagsKey() {
        return ClaimRequest.tags(tags);
    }

    /** The terms given, or null when they were left blank. */
    public Integer termsDays() {
        return terms == null || terms.isBlank() ? null : Integer.valueOf(terms.trim());
    }

    /** The from-date given, or null when it was left blank. */
    public LocalDate gradeFromDate() {
        return gradeFrom == null || gradeFrom.isBlank() ? null : LocalDate.parse(gradeFrom.trim());
    }

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    /** The request as the person rules accept it, or refused. */
    public static PersonRequest checked(PersonRequest request) throws InvalidSheetRequestException {
        if (request == null || request.name() == null || request.name().isBlank()) {
            throw new InvalidSheetRequestException("A name is required");
        }
        if (request.grade() == null || !GRADES.contains(request.grade())) {
            throw new InvalidSheetRequestException("The grade must be A, B or C");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidSheetRequestException("Not a date (yyyy-mm-dd): " + from);
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,4}")) {
            throw new InvalidSheetRequestException("Terms must be a whole number of days: " + terms);
        }
        // Names are kept without the spaces around them.
        return new PersonRequest(request.name().trim(), request.grade(), request.user(), request.version(), from, terms,
                request.contactKey(), request.tags());
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.List;

/** A person as the screen sees it, with their statement count, and the last statement's due-total
 *  (two decimals, null when it was n/a or none was taken) and date (yyyy-mm-dd, null when none was),
 *  and whether they are retired and from when (yyyy-mm-dd, null when not retired), and each past
 *  retirement's dates, in the order they ended,
 *  and whether they have any hold and each hold's dates, and the ids of the people they have named as patrons. `grade` is
 *  the grade in force on the sheet's today; `grades` every grade recorded, by from-date (null: from
 *  the beginning of time, first); `terms` the person's own terms (null: none); `contact` their
 *  contact (null: none); `aliases` their aliases, sorted as names are compared; `clashing` whether
 *  their name or an alias is used on another sheet of their sheet's tree; `origin` the sheet they were
 *  transferred from (null: they were not); `tags` their tags, sorted (empty: none);
 *  `snapshots` their snapshot lines, oldest first ("<day left> <due-total>");
 *  `statementLines` their statements still standing, oldest first ("<statement date> <due-total>"). */
public record PersonResponse(long id, String name, String grade, int version, int statementCount,
        String statedTotal, String statementDate, boolean retired, String retiredFrom,
        List<RetirementDates> pastRetirements,
        boolean held, List<HoldDates> holds, List<Long> patrons, List<GradeFrom> grades, Integer terms,
        String contact, List<String> aliases, boolean clashing, String origin, List<String> tags,
        List<String> snapshots, List<String> statementLines) {

    /** A hold's dates (yyyy-mm-dd; `to` null: open-ended). */
    public record HoldDates(String from, String to) {
    }

    /** A past retirement's dates (yyyy-mm-dd): retired from `from`, unretired on `to`. */
    public record RetirementDates(String from, String to) {
    }

    public record GradeFrom(String grade, String from) {
    }

    public static PersonResponse from(Person person) {
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(), person.getVersion(),
                person.getStatementCount(),
                person.getStatedTotal() != null ? person.getStatedTotal().toPlainString() : null,
                person.getStatementDate() != null ? person.getStatementDate().toString() : null,
                person.isRetired(), person.getRetiredFrom() != null ? person.getRetiredFrom().toString() : null,
                person.getPastRetirements().stream()
                        .map(r -> new RetirementDates(r.from().toString(), r.to().toString()))
                        .toList(),
                person.isHeld(),
                person.getHolds().stream()
                        .map(h -> new HoldDates(h.from().toString(), h.to() != null ? h.to().toString() : null))
                        .toList(),
                List.copyOf(person.getPatronIds()),
                person.getGrades().entrySet().stream()
                        .map(e -> new GradeFrom(e.getValue(), e.getKey().equals(LocalDate.MIN) ? null : e.getKey().toString()))
                        .toList(),
                person.getTerms(), person.getContact(), List.copyOf(person.getAliases()),
                person.isClashing(), person.getOriginSheet(),
                person.getTags() == null ? List.of() : List.of(person.getTags().split(",")),
                List.copyOf(person.getSnapshots()), List.copyOf(person.getStatementLines()));
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet. `id` is null until the person is first saved. */
public class Person {
    private Long id;
    private final String sheetId;
    private String name;
    /** The person's grades by the date each is in force from; LocalDate.MIN for the first one,
     *  which applies from the beginning of time. */
    private TreeMap<LocalDate, String> grades = new TreeMap<>();
    /** The sheet's today as it was when the person was read (null: the person is new). */
    private LocalDate today;
    /** A grade this save records, from its date (null: the save records none). */
    private DatedGrade newGrade;
    private int version;
    /** The person's own terms in days (null: none). */
    private Integer terms;
    /** Whether this save changes the person's own terms. */
    private boolean termsChanged;
    /** The person's contact (null: none). */
    private String contact;
    /** Whether this save changes the person's contact. */
    private boolean contactChanged;
    /** The person's tags, lower-cased, sorted and comma separated (null: none). */
    private String tags;
    /** The sheet the person was transferred from, and the name they had there (null: not transferred). */
    private String originSheet;
    private String originName;
    private int statementCount;
    private BigDecimal statedTotal;
    private LocalDate statementDate;
    private LocalDate retiredFrom;
    /** The person's ended retirements, in the order they ended. */
    private List<PastRetirement> pastRetirements = new ArrayList<>();
    private List<Hold> holds = new ArrayList<>();
    private List<String> snapshots = new ArrayList<>();
    private List<String> statementLines = new ArrayList<>();
    private List<Long> patronIds = new ArrayList<>();
    /** The person's aliases, sorted as names are compared. */
    private List<String> aliases = new ArrayList<>();
    /** Whether the person's name or an alias is used on another sheet of their sheet's tree. */
    private boolean clashing;

    public Person(Long id, String sheetId, String name, String grade) {
        this(id, sheetId, name, grade, 0);
    }

    public Person(Long id, String sheetId, String name, String grade, int version) {
        this.version = version;
        this.id = id;
        this.sheetId = sheetId;
        this.name = name;
