            int n = jdbc.update("UPDATE person SET name = ?, terms = ?, contact = ?, tags = ?, version = version + 1 WHERE id = ? AND version = ?",
                    person.getName(), person.getTerms(), person.getContact(), person.getTags(), person.getId(), person.getVersion());
            if (n == 0) return false;
